export const SOURCE='https://tnbankers.org/TBA/Foreclosure/Home-Public.aspx';
export function clean(s){return String(s||'').replace(/<[^>]*>/g,' ').replace(/&nbsp;|&#160;/g,' ').replace(/&amp;/g,'&').replace(/&quot;/g,'"').replace(/&#39;|&apos;/g,"'").replace(/&#(\d+);/g,(_,n)=>String.fromCharCode(Number(n))).replace(/\s+/g,' ').trim();}
export function date(s){const a=clean(s).match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);return a?`${a[3]}-${a[1].padStart(2,'0')}-${a[2].padStart(2,'0')}`:null;}
export function parseListings(html,retrievedAt=new Date().toISOString()){
 const items=[];for(const row of html.matchAll(/<tr\b[^>]*>[\s\S]*?<\/tr>/gi)){if(!row[0].includes('submissionID'))continue;const cells=[...row[0].matchAll(/<td\b[^>]*>([\s\S]*?)<\/td>/gi)].map(m=>m[1]);if(cells.length<8)continue;const id=cells[7].match(/submissionID=(\d+)/)?.[1];if(!id)continue;
 const saleDate=date(cells[0]),continuanceDate=date(cells[1]);items.push({id:'tba-'+id,sourceId:id,address:clean(cells[3]),city:clean(cells[2]),state:'TN',zip:clean(cells[4]),county:clean(cells[5])||null,trustee:clean(cells[6]),saleDate,continuanceDate,effectiveSaleDate:continuanceDate||saleDate,sourceUrl:`https://tnbankers.org/Foreclosure/Foreclosure-Listing.aspx?submissionID=${id}`,sourceName:'ForeclosureTennessee.com · Tennessee Bankers Association',retrievedAt,verification:'Source record fetched · sale status unverified',kind:'Foreclosure notice',dataMode:'Source snapshot',coords:null});
 }const total=Number(clean(html).match(/(\d+) items in \d+ pages/)?.[1])||null;return {items,total,sourceUrl:SOURCE,retrievedAt,coverage:'Accessible public index rows; not all Tennessee properties',warnings:['Third-party notices; not verified by the source administrator. Sale and ownership status require verification.']};
}
export async function fetchListings(){const r=await fetch(SOURCE,{headers:{'Accept':'text/html','User-Agent':'DealFinder/1.0 (public property notice research)'},signal:AbortSignal.timeout(18000)});if(!r.ok)throw Error('Public notice source returned '+r.status);const html=await r.text();const result=parseListings(html);if(!result.items.length)throw Error('Source layout changed or no listings were returned.');result.items=result.items.map(l=>({...l,dataMode:'Fetched public-source record'}));return result;}
export function parseDetail(html,id){const get=label=>clean(html.match(new RegExp('<p>\\s*<strong>'+label+':<\\/strong>\\s*([\\s\\S]*?)<\\/p>','i'))?.[1]);const pdfs=[...html.matchAll(/href="data:application\/pdf;base64,([A-Za-z0-9+/=\s]+)"/g)].map(m=>m[1].replace(/\s/g,''));return {id:'tba-'+id,postedDate:date(get('Posted')),saleDate:date(get('Sale Date')),continuanceDate:date(get('Continuance Date')),address:get('Property Address'),trustee:get('Trustee Name'),county:get('County'),zip:get('Zipcode'),retrievedAt:new Date().toISOString(),sourceUrl:`https://tnbankers.org/Foreclosure/Foreclosure-Listing.aspx?submissionID=${id}`,pdfs};}
